import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class StringComparatorTest {

    // Mock object for StringComparator
    private StringComparator comparator;

    // Set up the mock object before each test
    @BeforeEach
    void setUp() {
        comparator = spy(new StringComparator());
    }

    // Test for null strings
    @Test
    void testNullStrings() {
        // Use assertDoesNotThrow to ensure no exceptions occur
        assertDoesNotThrow(() -> comparator.compareStrings(null, null));
        assertDoesNotThrow(() -> comparator.compareStrings("hello", null));
        assertDoesNotThrow(() -> comparator.compareStrings(null, "hello"));
    }

    // Test for case sensitivity
    @Test
    void testCaseSensitivity() {
        assertDoesNotThrow(() -> {
            comparator.compareStrings("Hello", "hello");
            // Correct verification to check behavior, not string
            verify(comparator, never()).compareStrings("Hello", "hello");
        });
    }

    // Test for special character handling
    @Test
    void testSpecialCharacters() {
        assertDoesNotThrow(() -> {
            comparator.compareStrings("!@#$%^&*", "!@#$%^&*");
            verify(comparator, times(1)).compareStrings("!@#$%^&*", "!@#$%^&*");

            comparator.compareStrings("hello!", "hello");
            verify(comparator, never()).compareStrings("hello!", "hello");
        });
    }

    // Test for handling of long strings
    @Test
    void testLongStrings() {
        String longStr1 = "a".repeat(1000);
        String longStr2 = "a".repeat(1000);
        String differentLongStr = "b".repeat(1000);

        assertDoesNotThrow(() -> {
            comparator.compareStrings(longStr1, longStr2);
            verify(comparator, times(1)).compareStrings(longStr1, longStr2);

            comparator.compareStrings(longStr1, differentLongStr);
            verify(comparator, never()).compareStrings(longStr1, differentLongStr);
        });
    }

    // Test for whitespace comparison
    @Test
    void testWhitespaceStrings() {
        assertDoesNotThrow(() -> {
            comparator.compareStrings(" ", " ");
            verify(comparator, times(1)).compareStrings(" ", " ");

            comparator.compareStrings(" \t\n", " \t\n");
            verify(comparator, times(1)).compareStrings(" \t\n", " \t\n");

            comparator.compareStrings(" ", "");
            verify(comparator, never()).compareStrings(" ", "");
        });
    }

    // Test for Unicode character comparison
    @Test
    void testUnicodeStrings() {
        assertDoesNotThrow(() -> {
            comparator.compareStrings("こんにちは", "こんにちは");
            verify(comparator, times(1)).compareStrings("こんにちは", "こんにちは");

            comparator.compareStrings("こんにちは", "こんばんは");
            verify(comparator, never()).compareStrings("こんにちは", "こんばんは");
        });
    }

    // Test for numeric string comparison
    @Test
    void testNumericStrings() {
        assertDoesNotThrow(() -> {
            comparator.compareStrings("123", "123");
            verify(comparator, times(1)).compareStrings("123", "123");

            comparator.compareStrings("123", "0123");
            verify(comparator, never()).compareStrings("123", "0123");
        });
    }
}

