// Unit test for copyInputString
void testCopyInputString() {
    const char* testStr1 = "Hello, World!";
    int len1 = 13;
    char* result1 = copyInputString(testStr1, len1);
    assert(std::string(result1) == "Hello, World!");
    delete[] result1;

    const char* testStr2 = "";
    int len2 = 0;
    char* result2 = copyInputString(testStr2, len2);
    assert(std::string(result2) == "");
    delete[] result2;
}

// Unit test for trimWhitespace
void testTrimWhitespace() {
    char testStr1[] = "Test String   ";
    int len1 = 14;
    trimWhitespace(testStr1, len1);
    assert(std::string(testStr1) == "Test String");

    char testStr2[] = "NoSpaces";
    int len2 = 8;
    trimWhitespace(testStr2, len2);
    assert(std::string(testStr2) == "NoSpaces");
}

// Unit test for trimTrailingWhitespace
void testTrimTrailingWhitespace() {
    const char* testStr1 = "   EndsSpace ";
    int len1 = 13;
    char* result1 = trimTrailingWhitespace(testStr1, len1);
    assert(std::string(result1) == "   EndsSpace");
    delete[] result1;

    const char* testStr2 = "Trailing    ";
    int len2 = 11;
    char* result2 = trimTrailingWhitespace(testStr2, len2);
    assert(std::string(result2) == "Trailing");
    delete[] result2;

    const char* testStr3 = "NoSpace";
    int len3 = 7;
    char* result3 = trimTrailingWhitespace(testStr3, len3);
    assert(std::string(result3) == "NoSpace");
    delete[] result3;
}

int main() {
    testCopyInputString();
    testTrimWhitespace();
    testTrimTrailingWhitespace();

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

