    delete[] result;
}

void testNonStandardWhitespaceCharacters() {
    // Description: Use of non-standard whitespace characters
    char str[] = "String\xA0";
    char* result = trimTrailingWhitespace(str, 7);
    assertStringsEqual("String", result);
    delete[] result;
}

