    char* block = allocate_memory(50);
    assert(block != NULL);

    // Intentionally not freeing to simulate memory leak
    // Use tools like valgrind outside of this test to check for actual leaks
}

// Heap Corruption Detection
void test_heap_corruption() {
    // Allocate and free
    char* block1 = allocate_memory(50);
    assert(block1 != NULL);
    free_memory(block1);

    char* block2 = allocate_memory(100);
    assert(block2 != NULL);
    free_memory(block2);

    char* block3 = allocate_memory(200);
    assert(block3 != NULL);
    free_memory(block3);

    // Check for heap corruption using external tools
}

// Boundary Testing
void test_boundary_conditions() {
    // Allocate zero bytes
    char* block_zero = allocate_memory(0);
    assert(block_zero != NULL); // Depending on implementation, zero may return a valid pointer

    // Allocate a very large size
    char* block_large = allocate_memory(1000000000);
    assert(block_large == NULL); // Expect NULL if the size is too large
}

// Function to be used for multithreaded access
void* perform_allocations(void* arg __attribute__((unused))) {
    for (int i = 0; i < 100; ++i) {
        char* block = allocate_memory(50);
        if (block)
            free_memory(block);
    }
    return NULL;
}

// Concurrent Access
void test_concurrent_access() {
    pthread_t threads[10];
    // Create threads for concurrent memory allocation and freeing
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, perform_allocations, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Invalid Pointer Freeing
void test_invalid_pointer_free() {
    // Arbitrary non-heap pointer
    char stack_variable;
    free_memory(&stack_variable); // Should handle invalid free gracefully
}

