import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

class DatabaseConnectionTest {

    @Test
    void testCreateConnectionWithValidCredentials() {
        try {
            Connection connection = DatabaseConnection.createConnection("jdbc:mysql://localhost:3306/mydb", "validUser", "validPassword");
            assertNotNull(connection);
            connection.close();
        } catch (SQLException e) {
            fail("SQLException should not occur with valid credentials: " + e.getMessage());
        }
    }

    @Test
    void testCreateConnectionWithInvalidCredentials() {
        assertThrows(SQLException.class, () -> {
            DatabaseConnection.createConnection("jdbc:mysql://localhost:3306/mydb", "invalidUser", "invalidPassword");
        });
    }

    @Test
    void testCreateConnectionWithInvalidUrl() {
        assertThrows(SQLException.class, () -> {
            DatabaseConnection.createConnection("invalid-url", "user", "pass");
        });
    }

    @Test
    void testCreateConnectionWithoutDriver() throws SQLException {
        // Mocking DriverManager to simulate missing driver
        DriverManager mockDriverManager = mock(DriverManager.class);

        // Mocking the behavior of getConnection to throw SQLException
        when(mockDriverManager.getConnection(anyString(), anyString(), anyString()))
            .thenThrow(new SQLException("No suitable driver found"));

        // Verifying that SQLException is thrown with the expected message
        SQLException exception = assertThrows(SQLException.class, () -> {
            DatabaseConnection.createConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");
        });

        // Asserting the exception message
        assertEquals("No suitable driver found", exception.getMessage());

        // Resetting the mock to avoid side effects
        reset(mockDriverManager);
    }
}

