#include <iostream>
#include <string>
#include "cwe_126_2.cpp"

static int test_failures = 0;
static int test_pass = 0;

#define assert(expr) \
    do { \
        if (!(expr)) { \
            test_failures++; \
        } else { \
            test_pass++; \
        } \
        std::cout << "tests failed: " << test_failures << ", tests passed: " << test_pass << std::endl; \
