import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

// Import necessary classes for handling I/O streams
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;

class StringComparerTest {

    // Test when both strings are equal
    @Test
    void testCompareStringsEqual() {
        // Preserve the original System.out
        PrintStream originalOut = System.out;
        // Create a new output stream
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        // Set the new output stream as the current System.out
        System.setOut(new PrintStream(outputStream));

        // Call the method under test
        StringComparer.compareStrings("hello", "hello");

        // Restore the original System.out
        System.setOut(originalOut);
        // Assert that the expected output is produced
        assertEquals("str1 equals str2\n", outputStream.toString());
    }

    // Test when strings are not equal
    @Test
    void testCompareStringsNotEqual() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outputStream));

        StringComparer.compareStrings("hello", "world");

        System.setOut(originalOut);
        assertEquals("", outputStream.toString());
    }

    // Test with empty strings
    @Test
    void testCompareStringsEmpty() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outputStream));

        StringComparer.compareStrings("", "");

        System.setOut(originalOut);
        assertEquals("str1 equals str2\n", outputStream.toString());
    }

    // Test with different casing
    @Test
    void testCompareStringsDifferentCase() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outputStream));

        StringComparer.compareStrings("Java", "java");

        System.setOut(originalOut);
        assertEquals("", outputStream.toString());
    }

    // Test with whitespace strings
    @Test
    void testCompareStringsWhitespace() {
        PrintStream originalOut = System.out;
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outputStream));

