}

import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class StringComparerTest {

    // Null Input Tests
    @Test
    void testNullInputs() {
        // Test when both inputs are null
        assertDoesNotThrow(() -> StringComparer.compareStrings(null, null));

        // Test when first input is null
        assertDoesNotThrow(() -> StringComparer.compareStrings(null, "test"));

        // Test when second input is null
        assertDoesNotThrow(() -> StringComparer.compareStrings("test", null));
    }

    // Injection Attack Tests
    @Test
    void testInjectionAttackStrings() {
        // Test strings that resemble SQL injection
        assertDoesNotThrow(() -> StringComparer.compareStrings("hello'; DROP TABLE users; --", "hello'; DROP TABLE users; --"));

        // Test strings with potential command injection
        assertDoesNotThrow(() -> StringComparer.compareStrings("' OR '1'='1", "' OR '1'='1"));
    }

    // Unicode and Encoding Tests
    @Test
    void testUnicodeStrings() {
        // Test strings with Japanese characters
        assertDoesNotThrow(() -> StringComparer.compareStrings("こんにちは", "こんにちは"));

        // Test strings with Arabic characters
        assertDoesNotThrow(() -> StringComparer.compareStrings("مرحبا", "مرحبا"));
    }

    // Whitespace and Special Character Tests
    @Test
    void testWhitespaceAndSpecialCharacters() {
        // Test strings with leading and trailing spaces
        assertDoesNotThrow(() -> StringComparer.compareStrings(" test ", " test "));

        // Test strings with special characters
        assertDoesNotThrow(() -> StringComparer.compareStrings("!@#$%", "!@#$%"));
    }

    // Case Sensitivity Test
    @Test
    void testCaseSensitivity() {
        // Test strings differing only by case
        assertDoesNotThrow(() -> StringComparer.compareStrings("Case", "case"));
    }

    // Performance with Large Inputs Test
    @Test
    void testLargeInputs() {
        // Create a large string for testing
        String largeString = "a".repeat(1000000); // 1 million characters

        // Test with large identical strings
        assertDoesNotThrow(() -> StringComparer.compareStrings(largeString, largeString));
    }

    // Substring and Similarity Test
    @Test
    void testSubstringSimilarity() {
        // Test that substrings are not considered equal
        assertDoesNotThrow(() -> StringComparer.compareStrings("substring", "string"));
    }
}

