bool is_host_trusted(const std::string& ip, const std::string& trusted_host) {
    struct sockaddr_in sa;
    char host[1024];

    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;

    // Convert IP string to network address
    if (inet_pton(AF_INET, ip.c_str(), &sa.sin_addr) != 1) {
        return false; // invalid IP
    }

    // Reverse DNS lookup
    if (getnameinfo((struct sockaddr*)&sa, sizeof(sa), host, sizeof(host),
                    nullptr, 0, NI_NAMEREQD) != 0) {
        return false; // unable to resolve hostname
    }

    // Compare resolved hostname to trusted host
    return trusted_host == host;
}

// Test case 1: IP address resolves to the trusted host name
