from cwe_283_0 import terminate_process
import pytest
import os
import signal

def test_terminate_process_valid_pid():
    # Create a new process and get its PID
    pid = os.fork()
    if pid == 0:
        while True:
            pass  # Child process runs indefinitely
    else:
        os.kill(pid, signal.SIGKILL)  # Cleanup after test

    # Assuming the child process still exists before the test
    try:
        terminate_process(pid, signal.SIGTERM)
    except ProcessLookupError:
        assert False, "Process should exist before SIGTERM is sent."

def test_terminate_process_invalid_pid():
    invalid_pid = 999999  # Assuming this PID does not exist

    with pytest.raises(ProcessLookupError):
        terminate_process(invalid_pid, signal.SIGTERM)

def test_terminate_process_permission_denied():
    system_pid = 1  # Assuming PID 1 is a protected system process

    if os.geteuid() != 0:  # Avoid running as root
        with pytest.raises(PermissionError):
            terminate_process(system_pid, signal.SIGTERM)

def test_terminate_process_with_invalid_signal():
    pid = os.fork()
    if pid == 0:
        while True:
            pass  # Child process runs indefinitely
    else:
        try:
            with pytest.raises(OSError):
                terminate_process(pid, -1)  # Invalid signal
        finally:
            os.kill(pid, signal.SIGKILL)  # Cleanup

def test_terminate_process_ownership():
    # Attempt to send a signal to a process not owned by the test user
    # Requires a known PID of a process owned by another user (not easily testable)
    other_user_pid = 1  # Change to a valid PID owned by another user

    if os.geteuid() != 0:  # Avoid running as root
        with pytest.raises(PermissionError):
            terminate_process(other_user_pid, signal.SIGKILL)

def test_terminate_process_race_condition():
    pid = os.fork()
    if pid == 0:
        os._exit(0)  # Exit immediately
    else:
        try:
            terminate_process(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass  # Expected, as the process may have exited

def test_terminate_process_no_sensitive_info_leak():
    invalid_pid = 999999

    try:
        terminate_process(invalid_pid, signal.SIGTERM)
    except OSError as e:
        assert "Error" in str(e)
        assert "Process" not in str(e)  # Ensure no sensitive info is leaked

