            def __reduce__(self):
                return (eval, ("print(1+2)",))
        attack = Attack()
        pickled_data = pickle.dumps(attack)

        with self.assertRaises(TypeError):
            response = self.app.get(f'/unpickled_data?data={pickled_data.hex()}')

