#include <fstream>

// Helper function to create test files
void createTestFile(const std::string& fileName, const std::string& content) {
    std::ofstream file(fileName);
    if (file) {
        file << content;
    }
    file.close();
}

int main() {
    // Test 1: File with a single word
    createTestFile("test1.txt", "Hello");
    std::string content1 = readFile("test1.txt");
    assert(content1 == "Hello");
    outputContent(content1); // Expected output: Hello

    // Test 2: File with multiple words
    createTestFile("test2.txt", "foo bar baz");
    std::string content2 = readFile("test2.txt");
    assert(content2 == "foo");
    outputContent(content2); // Expected output: foo

    // Test 3: Empty file
    createTestFile("test3.txt", "");
    std::string content3 = readFile("test3.txt");
    assert(content3.empty());
    outputContent(content3); // Expected output: (no output)

    // Test 4: File with leading spaces
    createTestFile("test4.txt", "    leading space");
    std::string content4 = readFile("test4.txt");
    assert(content4.empty());
    outputContent(content4); // Expected output: (no output)

    // Test 5: File with only spaces
    createTestFile("test5.txt", "    ");
    std::string content5 = readFile("test5.txt");
    assert(content5.empty());
    outputContent(content5); // Expected output: (no output)

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

